6	// AscendC KV RMSNorm + RoPE + Cache kernel (Norm mode only)
7	// Supports float16 and bfloat16
8	// Fused: RMSNorm(rms_part) + RoPE(rope_part) + cache scatter-write
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 1;
13	
14	// ---------------------------------------------------------------------------
15	// Inline helpers
16	// ---------------------------------------------------------------------------
17	
18	template <typename T>
19	__aicore__ inline void LoadGmToUb(
20	    AscendC::LocalTensor<T> &dst,
21	    const AscendC::GlobalTensor<T> &src,
22	    uint32_t count)
23	{
24	    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
25	    AscendC::DataCopyPadExtParams<T> pad{true, 0, 0, static_cast<T>(0)};
26	    AscendC::DataCopyPad(dst, src, p, pad);
27	}
28	
29	template <typename T>
30	__aicore__ inline void StoreUbToGm(
31	    const AscendC::GlobalTensor<T> &dst,
32	    AscendC::LocalTensor<T> &src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPad(dst, src, p);
37	}
38	
39	// =========================================================================
40	// KV RMSNorm RoPE Cache Kernel
41	// =========================================================================
42	
43	template <typename dataType>
44	class KvRmsnormRopeCacheKernel {
45	public:
46	    __aicore__ inline void Init(
47	        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin,
48	        GM_ADDR index, GM_ADDR k_cache, GM_ADDR ckv_cache,
49	        int32_t B, int32_t S, int32_t rmsSize, int32_t ropeSize,
50	        int32_t cacheLen, int32_t usedCoreNum, int32_t tasksPerCore,
51	        int32_t rowsPerCore, float epsilon, float invRmsDim)
52	    {
53	        B_ = B; S_ = S; rmsSize_ = rmsSize; ropeSize_ = ropeSize;
54	        totalHidden_ = rmsSize + ropeSize;
55	        cacheLen_ = cacheLen; usedCoreNum_ = usedCoreNum;
56	        tasksPerCore_ = tasksPerCore; rowsPerCore_ = rowsPerCore;
57	        epsilon_ = epsilon; invRmsDim_ = invRmsDim;
58	
59	        kvGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(kv),
60	                              static_cast<uint64_t>(B) * S * totalHidden_);
61	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), rmsSize);
62	        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos),
63	                               static_cast<uint64_t>(B) * S * ropeSize);
64	        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin),
65	                               static_cast<uint64_t>(B) * S * ropeSize);
66	        indexGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(index),
67	                                 static_cast<uint64_t>(B) * S);
68	        kCacheGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(k_cache),
69	                                  static_cast<uint64_t>(B) * cacheLen * ropeSize);
70	        ckvCacheGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(ckv_cache),
71	                                    static_cast<uint64_t>(B) * cacheLen * rmsSize);
72	
73	        if ASCEND_IS_AIV { InitBuffers(); }
74	    }
75	
76	    __aicore__ inline void Process()
77	    {
78	        if ASCEND_IS_AIV {
79	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
80	
81	            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
82	                const int rowBlockStart =
83	                    coreIdx * tasksPerCore_ * rowsPerCore_ + localIdx * rowsPerCore_;
84	                if (rowBlockStart >= B_ * S_) { continue; }
85	
86	                int validRows = rowsPerCore_;
87	                if (rowBlockStart + validRows > B_ * S_) {
88	                    validRows = B_ * S_ - rowBlockStart;
89	                }
90	
91	                for (int r = 0; r < validRows; ++r) {
92	                    const int flatIdx = rowBlockStart + r;
93	                    const int b = flatIdx / S_;
94	                    const int s = flatIdx % S_;
95	                    ProcessRow(b, s);
96	                }
97	            }
98	        }
99	    }
100	
101	private:
102	    // -----------------------------------------------------------------------
103	    // Buffer init
104	    // -----------------------------------------------------------------------
105	
106	    __aicore__ inline void InitBuffers()
107	    {
108	        // RMSNorm: rmsSize = 512
109	        pipe_.InitBuffer(rmsInQueue_, BUFFER_NUM, rmsSize_ * sizeof(dataType));
110	        pipe_.InitBuffer(rmsOutQueue_, BUFFER_NUM, rmsSize_ * sizeof(dataType));
111	        pipe_.InitBuffer(gammaBuf_, rmsSize_ * sizeof(dataType));
112	        pipe_.InitBuffer(reduceBuf_, rmsSize_ * sizeof(float));
113	        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
114	        pipe_.InitBuffer(rmsValBuf_, sizeof(float));
115	
116	        // RoPE: ropeSize = 64
117	        pipe_.InitBuffer(ropeInQueue_, BUFFER_NUM, ropeSize_ * sizeof(dataType));
118	        pipe_.InitBuffer(cosInQueue_, BUFFER_NUM, ropeSize_ * sizeof(dataType));
119	        pipe_.InitBuffer(sinInQueue_, BUFFER_NUM, ropeSize_ * sizeof(dataType));
120	        pipe_.InitBuffer(ropeOutQueue_, BUFFER_NUM, ropeSize_ * sizeof(dataType));
121	
122	        // Intermediate fp32 compute for RoPE
123	        const int halfRope = ropeSize_ / 2;  // 32
124	        pipe_.InitBuffer(kEvenBuf_, halfRope * sizeof(float));
125	        pipe_.InitBuffer(kOddBuf_, halfRope * sizeof(float));
126	        pipe_.InitBuffer(cosFp32Buf_, ropeSize_ * sizeof(float));
127	        pipe_.InitBuffer(sinFp32Buf_, ropeSize_ * sizeof(float));
128	        pipe_.InitBuffer(tmpMulBuf_, ropeSize_ * sizeof(float));
129	
130	        // Cast buffers (fp16/bf16)
131	        if constexpr (!std::is_same_v<dataType, float>) {
132	            pipe_.InitBuffer(rmsCastBuf_, rmsSize_ * sizeof(float));
133	            pipe_.InitBuffer(gammaCastBuf_, rmsSize_ * sizeof(float));
134	            pipe_.InitBuffer(rmsOutCastBuf_, rmsSize_ * sizeof(float));
135	            pipe_.InitBuffer(ropeCastBuf_, ropeSize_ * sizeof(float));
136	            pipe_.InitBuffer(cosCastBuf_, ropeSize_ * sizeof(float));
137	            pipe_.InitBuffer(sinCastBuf_, ropeSize_ * sizeof(float));
138	            pipe_.InitBuffer(ropeOutCastBuf_, ropeSize_ * sizeof(float));
139	        }
140	
141	        PreloadGamma();
142	    }
143	
144	    __aicore__ inline void PreloadGamma()
145	    {
146	        gammaLocalIn_ = gammaBuf_.Get<dataType>();
147	        LoadGmToUb(gammaLocalIn_, gammaGM_, static_cast<uint32_t>(rmsSize_));
148	        AscendC::PipeBarrier<PIPE_MTE2>();
149	        AscendC::PipeBarrier<PIPE_ALL>();
150	
151	        if constexpr (std::is_same_v<dataType, float>) {
152	            gammaLocalFp32_ = gammaLocalIn_.template ReinterpretCast<float>();
153	        } else {
154	            gammaLocalFp32_ = gammaCastBuf_.Get<float>();
155	            AscendC::Cast(gammaLocalFp32_, gammaLocalIn_,
156	                          AscendC::RoundMode::CAST_NONE, rmsSize_);
157	            AscendC::PipeBarrier<PIPE_V>();
158	        }
159	    }
160	
161	    // -----------------------------------------------------------------------
162	    // Per-row processing
163	    // -----------------------------------------------------------------------
164	
165	    __aicore__ inline void ProcessRow(int32_t b, int32_t s)
166	    {
167	        // 1. Read cache index
168	        const uint64_t idxOff = static_cast<uint64_t>(b) * S_ + s;
169	        AscendC::PipeBarrier<PIPE_ALL>();
170	        int64_t cacheIdx = indexGM_.GetValue(idxOff);
171	        AscendC::PipeBarrier<PIPE_ALL>();
172	
173	        if (cacheIdx < 0 || cacheIdx >= static_cast<int64_t>(cacheLen_)) { return; }
174	
175	        // 2. Process RMSNorm + write to ckv_cache
176	        CopyInRms(b, s);
177	        ComputeRmsNorm();
178	        WriteCacheRms(b, static_cast<int32_t>(cacheIdx));
179	
180	        // 3. Process RoPE + write to k_cache
181	        CopyInRopeKv(b, s);
182	        CopyInCos(b, s);
183	        CopyInSin(b, s);
184	        ComputeRope();
185	        WriteCacheRope(b, static_cast<int32_t>(cacheIdx));
186	    }
187	
188	    // =======================================================================
189	    // RMSNorm
190	    // =======================================================================
191	
192	    __aicore__ inline void CopyInRms(int32_t b, int32_t s)
193	    {
194	        const uint64_t off = static_cast<uint64_t>(b) * S_ * totalHidden_
195	                            + static_cast<uint64_t>(s) * totalHidden_;
196	        rmsInLocal_ = rmsInQueue_.AllocTensor<dataType>();
197	        LoadGmToUb(rmsInLocal_, kvGM_[off], static_cast<uint32_t>(rmsSize_));
198	        rmsInQueue_.EnQue(rmsInLocal_);
199	    }
200	
201	    __aicore__ inline void ComputeRmsNorm()
202	    {
203	        rmsOutLocal_ = rmsOutQueue_.AllocTensor<dataType>();
204	
205	        rmsInLocal_ = rmsInQueue_.DeQue<dataType>();
206	        auto reduceLocal = reduceBuf_.Get<float>();
207	        auto sumLocal = sumBuf_.Get<float>();
208	        auto rmsValLocalFp32 = rmsValBuf_.Get<float>();
209	
210	        // Cast input → fp32
211	        PrepareInput(rmsLocalFp32_, rmsInLocal_, rmsCastBuf_, rmsSize_);
212	        // Prepare output
213	        PrepareOutput(rmsOutLocalFp32_, rmsOutLocal_, rmsOutCastBuf_, rmsSize_);
214	
215	        // sum of squares
216	        AscendC::Mul(rmsOutLocalFp32_, rmsLocalFp32_, rmsLocalFp32_, rmsSize_);
217	        AscendC::ReduceSum<float>(sumLocal, rmsOutLocalFp32_, reduceLocal, rmsSize_);
218	
219	        // 1/sqrt(mean + eps)
220	        const float meanSq = sumLocal.GetValue(0) * invRmsDim_ + epsilon_;
221	        AscendC::PipeBarrier<PIPE_ALL>();
222	        AscendC::Duplicate(sumLocal, meanSq, 1);
223	        AscendC::Rsqrt(rmsValLocalFp32, sumLocal, 1);
224	        AscendC::PipeBarrier<PIPE_ALL>();
225	        const float invRms = rmsValLocalFp32.GetValue(0);
226	        AscendC::PipeBarrier<PIPE_ALL>();
227	
228	        // normalize * gamma
229	        AscendC::Muls(rmsOutLocalFp32_, rmsLocalFp32_, invRms, rmsSize_);
230	        AscendC::Mul(rmsOutLocalFp32_, rmsOutLocalFp32_, gammaLocalFp32_, rmsSize_);
231	
232	        // Cast back
233	        FinalizeOutput(rmsOutLocal_, rmsOutLocalFp32_, rmsSize_);
234	
235	        rmsInQueue_.FreeTensor(rmsInLocal_);
236	        rmsOutQueue_.EnQue(rmsOutLocal_);
237	    }
238	
239	    __aicore__ inline void WriteCacheRms(int32_t b, int32_t cacheIdx)
240	    {
241	        const uint64_t off = static_cast<uint64_t>(b) * cacheLen_ * rmsSize_
242	                            + static_cast<uint64_t>(cacheIdx) * rmsSize_;
243	        rmsOutLocal_ = rmsOutQueue_.DeQue<dataType>();
244	        StoreUbToGm(ckvCacheGM_[off], rmsOutLocal_, static_cast<uint32_t>(rmsSize_));
245	        rmsOutQueue_.FreeTensor(rmsOutLocal_);
246	    }
247	
248	    // =======================================================================
249	    // RoPE
250	    // =======================================================================
251	
252	    __aicore__ inline void CopyInRopeKv(int32_t b, int32_t s)
253	    {
254	        const uint64_t off = static_cast<uint64_t>(b) * S_ * totalHidden_
255	                            + static_cast<uint64_t>(s) * totalHidden_ + rmsSize_;
256	        ropeInLocal_ = ropeInQueue_.AllocTensor<dataType>();
257	        LoadGmToUb(ropeInLocal_, kvGM_[off], static_cast<uint32_t>(ropeSize_));
258	        ropeInQueue_.EnQue(ropeInLocal_);
259	    }
260	
261	    __aicore__ inline void CopyInCos(int32_t b, int32_t s)
262	    {
263	        const uint64_t off = static_cast<uint64_t>(b) * S_ * ropeSize_
264	                            + static_cast<uint64_t>(s) * ropeSize_;
265	        cosInLocal_ = cosInQueue_.AllocTensor<dataType>();
266	        LoadGmToUb(cosInLocal_, cosGM_[off], static_cast<uint32_t>(ropeSize_));
267	        cosInQueue_.EnQue(cosInLocal_);
268	    }
269	
270	    __aicore__ inline void CopyInSin(int32_t b, int32_t s)
271	    {
272	        const uint64_t off = static_cast<uint64_t>(b) * S_ * ropeSize_
273	                            + static_cast<uint64_t>(s) * ropeSize_;
274	        sinInLocal_ = sinInQueue_.AllocTensor<dataType>();
275	        LoadGmToUb(sinInLocal_, sinGM_[off], static_cast<uint32_t>(ropeSize_));
276	        sinInQueue_.EnQue(sinInLocal_);
277	    }
278	
279	    __aicore__ inline void ComputeRope()
280	    {
281	        ropeOutLocal_ = ropeOutQueue_.AllocTensor<dataType>();
282	
283	        // DeQue all inputs
284	        ropeInLocal_ = ropeInQueue_.DeQue<dataType>();
285	        cosInLocal_ = cosInQueue_.DeQue<dataType>();
286	        sinInLocal_ = sinInQueue_.DeQue<dataType>();
287	
288	        const int halfRope = ropeSize_ / 2;  // 32
289	
290	        // Cast rope input → fp32
291	        PrepareInput(ropeLocalFp32_, ropeInLocal_, ropeCastBuf_, ropeSize_);
292	
293	        // Cast cos, sin → fp32
294	        auto cosFp32 = cosFp32Buf_.Get<float>();
295	        auto sinFp32 = sinFp32Buf_.Get<float>();
296	        PrepareInput(cosFp32, cosInLocal_, cosCastBuf_, ropeSize_);
297	        PrepareInput(sinFp32, sinInLocal_, sinCastBuf_, ropeSize_);
298	
299	        // Allocate work buffers
300	        auto kEvenFp32 = kEvenBuf_.Get<float>();
301	        auto kOddFp32 = kOddBuf_.Get<float>();
302	        auto rotateHalfFp32 = tmpMulBuf_.Get<float>();
303	
304	        // Build interleaved k and rotate_half using scalar extraction (32 pairs)
305	        // For pair i (x_{2i}, x_{2i+1}):
306	        //   k_even[i] = x_{2i}, k_odd[i] = x_{2i+1}
307	        //   k = (k_even, k_odd)  — interleaved
308	        //   rotate_half = (-k_odd, k_even)
309	        for (int i = 0; i < halfRope; ++i) {
310	            const float a = ropeLocalFp32_.GetValue(2 * i);
311	            const float b = ropeLocalFp32_.GetValue(2 * i + 1);
312	            kEvenFp32.SetValue(i, a);
313	            kOddFp32.SetValue(i, b);
314	        }
315	        AscendC::PipeBarrier<PIPE_V>();
316	
317	        // Build k in ropeLocalFp32_: [k_even(32), k_odd(32)]
318	        AscendC::DataCopy(ropeLocalFp32_, kEvenFp32, halfRope);
319	        AscendC::PipeBarrier<PIPE_V>();
320	        AscendC::DataCopy(ropeLocalFp32_[halfRope], kOddFp32, halfRope);
321	        AscendC::PipeBarrier<PIPE_V>();
322	
323	        // Build rotate_half = (-k_odd, k_even)
324	        AscendC::DataCopy(rotateHalfFp32, kOddFp32, halfRope);
325	        AscendC::PipeBarrier<PIPE_V>();
326	        AscendC::Muls(rotateHalfFp32, rotateHalfFp32, -1.0f, halfRope);
327	        AscendC::DataCopy(rotateHalfFp32[halfRope], kEvenFp32, halfRope);
328	        AscendC::PipeBarrier<PIPE_V>();
329	
330	        // k_embed = k * cos + rotate_half * sin
331	        AscendC::Mul(ropeLocalFp32_, ropeLocalFp32_, cosFp32, ropeSize_);
332	        AscendC::Mul(rotateHalfFp32, rotateHalfFp32, sinFp32, ropeSize_);
333	        AscendC::Add(ropeLocalFp32_, ropeLocalFp32_, rotateHalfFp32, ropeSize_);
334	
335	        // Cast back to original dtype
336	        FinalizeOutput(ropeOutLocal_, ropeLocalFp32_, ropeSize_);
337	
338	        ropeInQueue_.FreeTensor(ropeInLocal_);
339	        cosInQueue_.FreeTensor(cosInLocal_);
340	        sinInQueue_.FreeTensor(sinInLocal_);
341	        ropeOutQueue_.EnQue(ropeOutLocal_);
342	    }
343	
344	    __aicore__ inline void WriteCacheRope(int32_t b, int32_t cacheIdx)
345	    {
346	        const uint64_t off = static_cast<uint64_t>(b) * cacheLen_ * ropeSize_
347	                            + static_cast<uint64_t>(cacheIdx) * ropeSize_;
348	        ropeOutLocal_ = ropeOutQueue_.DeQue<dataType>();
349	        StoreUbToGm(kCacheGM_[off], ropeOutLocal_, static_cast<uint32_t>(ropeSize_));
350	        ropeOutQueue_.FreeTensor(ropeOutLocal_);
351	    }
352	
353	    // =======================================================================
354	    // Helpers: dtype casting
355	    // =======================================================================
356	
357	    template <typename SrcT>
358	    __aicore__ inline void PrepareInput(
359	        AscendC::LocalTensor<float> &dst,
360	        AscendC::LocalTensor<SrcT> &src,
361	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
362	        int32_t count)
363	    {
364	        if constexpr (std::is_same_v<SrcT, float>) {
365	            dst = src.template ReinterpretCast<float>();
366	        } else {
367	            dst = castBuf.Get<float>(count);
368	            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
369	            AscendC::PipeBarrier<PIPE_V>();
370	        }
371	    }
372	
373	    template <typename DstT>
374	    __aicore__ inline void PrepareOutput(
375	        AscendC::LocalTensor<float> &dst,
376	        AscendC::LocalTensor<DstT> &out,
377	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
378	        int32_t count)
379	    {
380	        if constexpr (std::is_same_v<DstT, float>) {
381	            dst = out.template ReinterpretCast<float>();
382	        } else {
383	            dst = castBuf.Get<float>(count);
384	            AscendC::Duplicate(out, static_cast<DstT>(0), count);
385	        }
386	    }
387	
388	    template <typename DstT>
389	    __aicore__ inline void FinalizeOutput(
390	        AscendC::LocalTensor<DstT> &out,
391	        AscendC::LocalTensor<float> &src,
392	        int32_t count)
393	    {
394	        if constexpr (!std::is_same_v<DstT, float>) {
395	            AscendC::RoundMode rm = AscendC::RoundMode::CAST_NONE;
396	            if constexpr (std::is_same_v<DstT, bfloat16_t>) {
397	                rm = AscendC::RoundMode::CAST_ROUND;
398	            }
399	            AscendC::Cast(out, src, rm, count);
400	            AscendC::PipeBarrier<PIPE_V>();
401	        }
402	    }
403	
404	    // =======================================================================
405	    // Members
406	    // =======================================================================
407	
408	    int32_t B_, S_, rmsSize_, ropeSize_, totalHidden_, cacheLen_;
409	    int32_t usedCoreNum_, tasksPerCore_, rowsPerCore_;
410	    float epsilon_, invRmsDim_;
411	
412	    AscendC::TPipe pipe_;
413	
414	    AscendC::GlobalTensor<dataType> kvGM_, gammaGM_, cosGM_, sinGM_;
415	    AscendC::GlobalTensor<dataType> kCacheGM_, ckvCacheGM_;
416	    AscendC::GlobalTensor<int64_t> indexGM_;
417	
418	    // Queues
419	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> rmsInQueue_, rmsOutQueue_;
420	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> ropeInQueue_, cosInQueue_, sinInQueue_;
421	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> ropeOutQueue_;
422	
423	    // TBufs
424	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_, reduceBuf_, sumBuf_, rmsValBuf_;
425	    AscendC::TBuf<AscendC::TPosition::VECCALC> kEvenBuf_, kOddBuf_, cosFp32Buf_, sinFp32Buf_, tmpMulBuf_;
426	    AscendC::TBuf<AscendC::TPosition::VECCALC> rmsCastBuf_, gammaCastBuf_, rmsOutCastBuf_;
427	    AscendC::TBuf<AscendC::TPosition::VECCALC> ropeCastBuf_, cosCastBuf_, sinCastBuf_, ropeOutCastBuf_;
428	
429	    // Local tensors
430	    AscendC::LocalTensor<dataType> rmsInLocal_, rmsOutLocal_;
431	    AscendC::LocalTensor<dataType> ropeInLocal_, cosInLocal_, sinInLocal_, ropeOutLocal_;
432	    AscendC::LocalTensor<dataType> gammaLocalIn_;
