23	std::vector<at::Tensor> kv_rmsnorm_rope_cache(
24	    const at::Tensor &kv,
25	    const at::Tensor &gamma,
26	    const at::Tensor &cos,
27	    const at::Tensor &sin,
28	    const at::Tensor &index,
29	    const at::Tensor &k_cache,
30	    const at::Tensor &ckv_cache,
31	    c10::optional<at::Tensor> k_rope_scale,
32	    c10::optional<at::Tensor> c_kv_scale,
33	    c10::optional<at::Tensor> k_rope_offset,
34	    c10::optional<at::Tensor> c_kv_offset,
35	    double epsilon,
36	    std::string cache_mode,
37	    bool is_output_kv)
38	{
