40	    TORCH_CHECK(cache_mode == "Norm", "Only Norm cache_mode is currently supported");
41	    TORCH_CHECK(kv.dim() == 4, "kv must be 4D [B, N, S, H]");
42	    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [rms_size]");
43	    TORCH_CHECK(
44	        kv.scalar_type() == at::kHalf || kv.scalar_type() == at::kBFloat16,
45	        "kv must be float16 or bfloat16");
46	    TORCH_CHECK(gamma.scalar_type() == kv.scalar_type(),
47	        "gamma must have the same dtype as kv");
48	
49	    int32_t B = static_cast<int32_t>(kv.sizes()[0]);
50	    int32_t N = static_cast<int32_t>(kv.sizes()[1]);
51	    int32_t S = static_cast<int32_t>(kv.sizes()[2]);
52	    int32_t totalHidden = static_cast<int32_t>(kv.sizes()[3]);
53	    int32_t rmsSize = static_cast<int32_t>(gamma.sizes()[0]);
54	    int32_t ropeSize = totalHidden - rmsSize;
55	    int32_t cacheLen = static_cast<int32_t>(k_cache.sizes()[2]);
