60	
61	    // Tiling
62	    int32_t totalRows = B * S;
63	    int32_t rowsPerCore = 1;  // process one row per iteration
64	    int32_t usedCoreNum = std::min(numCores, std::max(1, totalRows));
65	    int32_t tasksPerCore = (totalRows + usedCoreNum - 1) / usedCoreNum;
66	
67	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
