// FusedAddRmsnorm op_host: tiling + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>
#include <string>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_fused_add_rmsnorm_kernel.h"

namespace ascend_kernel {

at::Tensor fused_add_rmsnorm(
    const at::Tensor &hidden_states,
    const at::Tensor &residual,
    const at::Tensor &weight,
    double eps)
{
    // Input validation
    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be 2D [B, H]");
    TORCH_CHECK(residual.dim() == 2, "residual must be 2D [B, H]");
    TORCH_CHECK(weight.dim() == 1, "weight must be 1D [H]");
    TORCH_CHECK(
        hidden_states.scalar_type() == at::kFloat ||
        hidden_states.scalar_type() == at::kHalf ||
        hidden_states.scalar_type() == at::kBFloat16,
        "hidden_states must be float32, float16, or bfloat16");
    TORCH_CHECK(hidden_states.sizes() == residual.sizes(),
        "hidden_states and residual must have the same shape");
    TORCH_CHECK(hidden_states.sizes()[1] == weight.sizes()[0],
        "hidden_states dim 1 must match weight size");

    int32_t B = static_cast<int32_t>(hidden_states.sizes()[0]);
    int32_t H = static_cast<int32_t>(hidden_states.sizes()[1]);

    // Platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t numCores = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    int32_t dtypeSize = 4;  // fp32
    int32_t bufferCoefficient = 64;  // fp32

    if (hidden_states.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
        dtypeSize = 2;
        bufferCoefficient = 48;
    } else if (hidden_states.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
        dtypeSize = 2;
        bufferCoefficient = 48;
    }

    // Block-level tiling
    int32_t blockM = 64;
    int32_t mNum = B / blockM;
    if (mNum == 0) {
        mNum = 1;
        blockM = B;
    }
    int32_t usedCoreNum = std::min(numCores, mNum);
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // UB-level tiling: tileH based on UB capacity
    int32_t maxTileH = static_cast<int32_t>(ubSize) / (bufferCoefficient * dtypeSize);
    int32_t tileH = std::min(H, maxTileH);
    // 32-byte align
    int32_t alignElem = 32 / dtypeSize;
    tileH = (tileH / alignElem) * alignElem;
    if (tileH < 1) { tileH = alignElem; }

    int32_t numTilesH = H / tileH;
    int32_t lastTileH = H - numTilesH * tileH;
    if (lastTileH == 0) {
        lastTileH = tileH;
    } else {
        numTilesH += 1;
    }

    // Create output tensor
    auto output = at::empty_like(hidden_states);

    // All parameters must be left-values for EXEC_KERNEL_CMD
    float epsVal = static_cast<float>(eps);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

