5	
6	// AscendC FusedAddRmsnorm kernel
7	// Fused Add + RMSNorm: y = ((hidden_states + residual) * rsqrt(mean(x^2) + eps)) * weight
8	// Supports float32, float16, and bfloat16
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 2;
13	
14	// ---------------------------------------------------------------------------
15	// Inline helpers for data movement
16	// ---------------------------------------------------------------------------
17	
18	template <typename T>
19	__aicore__ inline void LoadGmToUb(
20	    AscendC::LocalTensor<T> &dst,
21	    const AscendC::GlobalTensor<T> &src,
22	    uint32_t count)
23	{
24	    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
25	    AscendC::DataCopyPadExtParams<T> pad{true, 0, 0, static_cast<T>(0)};
26	    AscendC::DataCopyPad(dst, src, p, pad);
27	}
28	
29	template <typename T>
30	__aicore__ inline void StoreUbToGm(
31	    const AscendC::GlobalTensor<T> &dst,
32	    AscendC::LocalTensor<T> &src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPad(dst, src, p);
37	}
38	
39	// =========================================================================
40	// FusedAddRmsnorm Kernel (single-row path)
41	// =========================================================================
42	
43	template <typename dataType>
44	class FusedAddRmsnormKernel {
45	public:
46	    __aicore__ inline void Init(
47	        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR output,
48	        int32_t B, int32_t H, int32_t usedCoreNum, int32_t tasksPerCore,
49	        int32_t blockM, int32_t mNum, int32_t tileH, int32_t numTilesH,
50	        int32_t lastTileH, float eps)
51	    {
52	        B_ = B; H_ = H; usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
53	        blockM_ = blockM; mNum_ = mNum; tileH_ = tileH;
54	        numTilesH_ = numTilesH; lastTileH_ = lastTileH; eps_ = eps;
55	
56	        uint64_t totalElem = static_cast<uint64_t>(B_) * H_;
57	
58	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), totalElem);
59	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), totalElem);
60	        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), static_cast<uint64_t>(H_));
61	        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), totalElem);
62	
63	        pipe_.InitBuffer(hsQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
64	        pipe_.InitBuffer(resQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
65	        pipe_.InitBuffer(wQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
66	        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
67	
68	        pipe_.InitBuffer(hsFp32Buf_, tileH_ * sizeof(float));
69	        pipe_.InitBuffer(resFp32Buf_, tileH_ * sizeof(float));
70	        pipe_.InitBuffer(xFp32Buf_, tileH_ * sizeof(float));
71	        pipe_.InitBuffer(wFp32Buf_, tileH_ * sizeof(float));
72	        pipe_.InitBuffer(yFp32Buf_, tileH_ * sizeof(float));
73	        pipe_.InitBuffer(sqFp32Buf_, tileH_ * sizeof(float));
74	
75	        // ReduceSum work buffer: ceilDiv(tileH, 64) * 64 elements
76	        int32_t reduceWorkCount = ((tileH_ + 63) / 64) * 64;
77	        pipe_.InitBuffer(reduceWorkBuf_, reduceWorkCount * sizeof(float));
78	        // Small buffer for sum accumulation (16 elements is enough)
79	        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
80	        // Scalar values
81	        pipe_.InitBuffer(sqSumBuf_, sizeof(float));
82	        pipe_.InitBuffer(rmsValBuf_, sizeof(float));
83	    }
84	
85	    __aicore__ inline void Process()
86	    {
87	        const int coreIdx = AscendC::GetBlockIdx();
88	
89	        for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
90	            int blockId = coreIdx * tasksPerCore_ + localIdx;
91	            if (blockId >= mNum_) { continue; }
92	
93	            int rowStart = blockId * blockM_;
94	            int actualRows = blockM_;
95	            if (blockId == mNum_ - 1) {
96	                actualRows = B_ - rowStart;
97	            }
98	
99	            for (int rowOff = 0; rowOff < actualRows; ++rowOff) {
100	                int rowIdx = rowStart + rowOff;
101	                ProcessRow(rowIdx);
102	            }
103	        }
104	    }
105	
106	private:
107	    __aicore__ inline void ProcessRow(int32_t rowIdx)
108	    {
109	        uint64_t rowOff = static_cast<uint64_t>(rowIdx) * H_;
110	
111	        // --- Phase 1: Compute sum(x^2) over H ---
112	        auto sqSumLocal = sqSumBuf_.Get<float>();
113	        AscendC::Duplicate(sqSumLocal, 0.0f, 1);
114	
115	        for (int t = 0; t < numTilesH_; ++t) {
116	            int32_t tLen = (t == numTilesH_ - 1) ? lastTileH_ : tileH_;
117	            uint64_t colOff = static_cast<uint64_t>(t) * tileH_;
118	
119	            // CopyIn: hidden_states and residual
120	            CopyInPhase1(rowOff + colOff, tLen);
121	
122	            // Compute: add + square + reduce + accumulate
123	            ComputePhase1(tLen);
124	
125	            // No CopyOut needed for Phase 1
126	        }
127	
128	        // Compute rms = rsqrt(sq_sum / H + eps)
129	        AscendC::PipeBarrier<PIPE_ALL>();
130	        float sqSum = sqSumLocal.GetValue(0);
131	        float invRmsDim = 1.0f / static_cast<float>(H_);
132	        float meanSq = sqSum * invRmsDim + eps_;
133	        auto rmsValLocal = rmsValBuf_.Get<float>();
134	        auto rmsInputLocal = sumBuf_.Get<float>();
135	        AscendC::Duplicate(rmsInputLocal, meanSq, 1);
136	        AscendC::PipeBarrier<PIPE_ALL>();
137	        AscendC::Rsqrt(rmsValLocal, rmsInputLocal, 1);
138	        AscendC::PipeBarrier<PIPE_ALL>();
139	        float invRms = rmsValLocal.GetValue(0);
140	        AscendC::PipeBarrier<PIPE_ALL>();
141	
142	        // --- Phase 2: Normalize and write output ---
143	        for (int t = 0; t < numTilesH_; ++t) {
144	            int32_t tLen = (t == numTilesH_ - 1) ? lastTileH_ : tileH_;
145	            uint64_t colOff = static_cast<uint64_t>(t) * tileH_;
146	
147	            // CopyIn: hidden_states, residual, and weight
148	            CopyInPhase2(rowOff + colOff, static_cast<uint32_t>(t) * tileH_, tLen);
149	
150	            // Compute: add + mul(rms) + mul(w) + cast
151	            ComputePhase2(tLen, invRms);
152	
153	            // CopyOut: write to output
154	            CopyOutPhase2(rowOff + colOff, tLen);
155	        }
156	    }
157	
158	    // -----------------------------------------------------------------------
159	    // Phase 1: reduction
160	    // -----------------------------------------------------------------------
161	
162	    __aicore__ inline void CopyInPhase1(uint64_t rowColOff, int32_t tLen)
163	    {
164	        // Load hidden_states tile
165	        hsLocal_ = hsQueue_.AllocTensor<dataType>();
166	        LoadGmToUb(hsLocal_, hsGM_[rowColOff], static_cast<uint32_t>(tLen));
167	        hsQueue_.EnQue(hsLocal_);
168	
169	        // Load residual tile
170	        resLocal_ = resQueue_.AllocTensor<dataType>();
171	        LoadGmToUb(resLocal_, resGM_[rowColOff], static_cast<uint32_t>(tLen));
172	        resQueue_.EnQue(resLocal_);
173	    }
174	
175	    __aicore__ inline void ComputePhase1(int32_t tLen)
176	    {
177	        // DeQue inputs
178	        hsLocal_ = hsQueue_.DeQue<dataType>();
179	        resLocal_ = resQueue_.DeQue<dataType>();
180	
181	        // Cast to fp32
182	        auto hsFp32 = CastInput(hsFp32Buf_, hsLocal_, tLen);
183	        auto resFp32 = CastInput(resFp32Buf_, resLocal_, tLen);
184	
185	        // x = hs + res
186	        auto xFp32 = xFp32Buf_.Get<float>(tLen);
187	        AscendC::Add(xFp32, hsFp32, resFp32, tLen);
188	
189	        // square: x^2
190	        auto sqFp32 = sqFp32Buf_.Get<float>(tLen);
191	        AscendC::Mul(sqFp32, xFp32, xFp32, tLen);
192	
193	        // Reduce sum over the tile
194	        auto reduceWork = reduceWorkBuf_.Get<float>();
195	        auto sumLocal = sumBuf_.Get<float>();
196	        AscendC::ReduceSum<float>(sumLocal, sqFp32, reduceWork, tLen);
197	
198	        // Barrier: wait for ReduceSum to complete before reading result
199	        AscendC::PipeBarrier<PIPE_V>();
200	
201	        // Accumulate sq_sum
202	        auto sqSumLocal = sqSumBuf_.Get<float>();
203	        AscendC::Adds(sqSumLocal, sqSumLocal, sumLocal.GetValue(0), 1);
204	
205	        // Barrier: wait for Adds to complete
206	        AscendC::PipeBarrier<PIPE_V>();
207	
208	        // Free input tensors
209	        hsQueue_.FreeTensor(hsLocal_);
210	        resQueue_.FreeTensor(resLocal_);
211	    }
212	
213	    // -----------------------------------------------------------------------
214	    // Phase 2: normalization
215	    // -----------------------------------------------------------------------
216	
217	    __aicore__ inline void CopyInPhase2(uint64_t rowColOff, uint32_t wOff, int32_t tLen)
218	    {
219	        // Load hidden_states tile
220	        hsLocal_ = hsQueue_.AllocTensor<dataType>();
221	        LoadGmToUb(hsLocal_, hsGM_[rowColOff], static_cast<uint32_t>(tLen));
222	        hsQueue_.EnQue(hsLocal_);
223	
224	        // Load residual tile
225	        resLocal_ = resQueue_.AllocTensor<dataType>();
226	        LoadGmToUb(resLocal_, resGM_[rowColOff], static_cast<uint32_t>(tLen));
227	        resQueue_.EnQue(resLocal_);
228	
229	        // Load weight tile
230	        wLocal_ = wQueue_.AllocTensor<dataType>();
231	        LoadGmToUb(wLocal_, wGM_[wOff], static_cast<uint32_t>(tLen));
232	        wQueue_.EnQue(wLocal_);
233	    }
234	
235	    __aicore__ inline void ComputePhase2(int32_t tLen, float invRms)
236	    {
237	        // Allocate output
238	        outLocal_ = outQueue_.AllocTensor<dataType>();
239	
240	        // DeQue inputs
241	        hsLocal_ = hsQueue_.DeQue<dataType>();
242	        resLocal_ = resQueue_.DeQue<dataType>();
243	        wLocal_ = wQueue_.DeQue<dataType>();
244	
245	        // Cast to fp32
246	        auto hsFp32 = CastInput(hsFp32Buf_, hsLocal_, tLen);
247	        auto resFp32 = CastInput(resFp32Buf_, resLocal_, tLen);
248	        auto wFp32 = CastInput(wFp32Buf_, wLocal_, tLen);
249	
250	        // x = hs + res
251	        auto xFp32 = xFp32Buf_.Get<float>(tLen);
252	        AscendC::Add(xFp32, hsFp32, resFp32, tLen);
253	
254	        // y = x * invRms
255	        auto yFp32 = yFp32Buf_.Get<float>(tLen);
256	        AscendC::Muls(yFp32, xFp32, invRms, tLen);
257	
258	        // y = y * w
259	        AscendC::Mul(yFp32, yFp32, wFp32, tLen);
260	
261	        // Cast back to original dtype
262	        CastOutput(outLocal_, yFp32, tLen);
263	
264	        // Barrier: wait for all compute to complete
