 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * SPDX-License-Identifier: BSD-3-Clause
 */

// AscendC FusedAddRmsnorm kernel — tiled approach
// Fused Add + RMSNorm: y = ((hidden_states + residual) * rsqrt(mean(x^2) + eps)) * weight
// Uses Sqrt + reciprocal for better precision matching PyTorch rsqrt.
// Supports float32, float16, and bfloat16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers for data movement
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pad{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, p, pad);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams p{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, p);
}

// =========================================================================
// FusedAddRmsnorm Kernel — tiled processing with Sqrt+Rcp
// =========================================================================

template <typename dataType>
class FusedAddRmsnormKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR output,
        int32_t B, int32_t H, int32_t usedCoreNum, int32_t tasksPerCore,
        int32_t blockM, int32_t mNum, int32_t tileH, int32_t numTilesH,
        int32_t lastTileH, float eps)
    {
        B_ = B; H_ = H; usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
        blockM_ = blockM; mNum_ = mNum; tileH_ = tileH;
        numTilesH_ = numTilesH; lastTileH_ = lastTileH; eps_ = eps;

        uint64_t totalElem = static_cast<uint64_t>(B_) * H_;
        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), totalElem);
        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), totalElem);
        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), static_cast<uint64_t>(H_));
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(output), totalElem);

        pipe_.InitBuffer(hsQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
        pipe_.InitBuffer(resQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
        pipe_.InitBuffer(wQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));
        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileH_ * sizeof(dataType));

        pipe_.InitBuffer(hsFp32Buf_, tileH_ * sizeof(float));
        pipe_.InitBuffer(resFp32Buf_, tileH_ * sizeof(float));
        pipe_.InitBuffer(xFp32Buf_, tileH_ * sizeof(float));
        pipe_.InitBuffer(wFp32Buf_, tileH_ * sizeof(float));
        pipe_.InitBuffer(yFp32Buf_, tileH_ * sizeof(float));
        pipe_.InitBuffer(sqFp32Buf_, tileH_ * sizeof(float));

        int32_t reduceWorkCount = ((tileH_ + 63) / 64) * 64;
        pipe_.InitBuffer(reduceWorkBuf_, reduceWorkCount * sizeof(float));
        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe_.InitBuffer(sqSumBuf_, sizeof(float));
        pipe_.InitBuffer(rmsValBuf_, sizeof(float));
        pipe_.InitBuffer(rmsSqrtBuf_, sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const int coreIdx = AscendC::GetBlockIdx();
        for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
            int blockId = coreIdx * tasksPerCore_ + localIdx;
            if (blockId >= mNum_) { continue; }
            int rowStart = blockId * blockM_;
            int actualRows = blockM_;
            if (blockId == mNum_ - 1) { actualRows = B_ - rowStart; }
            for (int rowOff = 0; rowOff < actualRows; ++rowOff) {
                ProcessRow(rowStart + rowOff);
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        uint64_t rowOff = static_cast<uint64_t>(rowIdx) * H_;

        // Phase 1: compute sum(x^2) over H tiles
        auto sqSumLocal = sqSumBuf_.Get<float>();
        AscendC::Duplicate(sqSumLocal, 0.0f, 1);
        AscendC::PipeBarrier<PIPE_V>();

        for (int t = 0; t < numTilesH_; ++t) {
            int32_t tLen = (t == numTilesH_ - 1) ? lastTileH_ : tileH_;
            uint64_t colOff = static_cast<uint64_t>(t) * tileH_;
            CopyInPhase1(rowOff + colOff, tLen);
            ComputePhase1(tLen, t == 0);
        }

        // Compute rms = 1/sqrt(sq_sum/H + eps)
        AscendC::PipeBarrier<PIPE_V>();
        float sqSum = sqSumLocal.GetValue(0);
        float invH = 1.0f / static_cast<float>(H_);
        float meanSq = sqSum * invH + eps_;

        // Use Sqrt + reciprocal instead of Rsqrt for better precision match
        auto sqrtLocal = rmsSqrtBuf_.Get<float>();
        AscendC::Duplicate(sqrtLocal, meanSq, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        AscendC::Sqrt(sqrtLocal, sqrtLocal, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float sqrtVal = sqrtLocal.GetValue(0);
        float invRms = 1.0f / sqrtVal;

        // Phase 2: normalize and write output
        for (int t = 0; t < numTilesH_; ++t) {
            int32_t tLen = (t == numTilesH_ - 1) ? lastTileH_ : tileH_;
            uint64_t colOff = static_cast<uint64_t>(t) * tileH_;
            CopyInPhase2(rowOff + colOff, static_cast<uint32_t>(t) * tileH_, tLen);
            ComputePhase2(tLen, invRms);
            CopyOutPhase2(rowOff + colOff, tLen);
        }
    }

    __aicore__ inline void CopyInPhase1(uint64_t rowColOff, int32_t tLen)
    {
        hsLocal_ = hsQueue_.AllocTensor<dataType>();
        LoadGmToUb(hsLocal_, hsGM_[rowColOff], static_cast<uint32_t>(tLen));
        hsQueue_.EnQue(hsLocal_);

        resLocal_ = resQueue_.AllocTensor<dataType>();
        LoadGmToUb(resLocal_, resGM_[rowColOff], static_cast<uint32_t>(tLen));
        resQueue_.EnQue(resLocal_);
    }

    __aicore__ inline void ComputePhase1(int32_t tLen, bool isFirst)
    {
        hsLocal_ = hsQueue_.DeQue<dataType>();
        resLocal_ = resQueue_.DeQue<dataType>();

        auto hsFp32 = CastInput(hsFp32Buf_, hsLocal_, tLen);
        auto resFp32 = CastInput(resFp32Buf_, resLocal_, tLen);

        auto xFp32 = xFp32Buf_.Get<float>(tLen);
        AscendC::Add(xFp32, hsFp32, resFp32, tLen);

        auto sqFp32 = sqFp32Buf_.Get<float>(tLen);
        AscendC::Mul(sqFp32, xFp32, xFp32, tLen);

        auto reduceWork = reduceWorkBuf_.Get<float>();
        // Initialize work buffer for first tile
        if (isFirst) {
            AscendC::Duplicate(reduceWork, 0.0f, ((tLen + 63) / 64) * 64);
            AscendC::PipeBarrier<PIPE_V>();
        }
        auto sumLocal = sumBuf_.Get<float>();
        AscendC::ReduceSum<float>(sumLocal, sqFp32, reduceWork, tLen);
        AscendC::PipeBarrier<PIPE_V>();

        auto sqSumLocal = sqSumBuf_.Get<float>();
        AscendC::Adds(sqSumLocal, sqSumLocal, sumLocal.GetValue(0), 1);
        AscendC::PipeBarrier<PIPE_V>();

        hsQueue_.FreeTensor(hsLocal_);
        resQueue_.FreeTensor(resLocal_);
    }

    __aicore__ inline void CopyInPhase2(uint64_t rowColOff, uint32_t wOff, int32_t tLen)
    {
        hsLocal_ = hsQueue_.AllocTensor<dataType>();
        LoadGmToUb(hsLocal_, hsGM_[rowColOff], static_cast<uint32_t>(tLen));
        hsQueue_.EnQue(hsLocal_);

        resLocal_ = resQueue_.AllocTensor<dataType>();
        LoadGmToUb(resLocal_, resGM_[rowColOff], static_cast<uint32_t>(tLen));
        resQueue_.EnQue(resLocal_);

        wLocal_ = wQueue_.AllocTensor<dataType>();
        LoadGmToUb(wLocal_, wGM_[wOff], static_cast<uint32_t>(tLen));
        wQueue_.EnQue(wLocal_);
    }

    __aicore__ inline void ComputePhase2(int32_t tLen, float invRms)
    {
        outLocal_ = outQueue_.AllocTensor<dataType>();
        hsLocal_ = hsQueue_.DeQue<dataType>();
        resLocal_ = resQueue_.DeQue<dataType>();
        wLocal_ = wQueue_.DeQue<dataType>();

        auto hsFp32 = CastInput(hsFp32Buf_, hsLocal_, tLen);
        auto resFp32 = CastInput(resFp32Buf_, resLocal_, tLen);
        auto wFp32 = CastInput(wFp32Buf_, wLocal_, tLen);

        auto xFp32 = xFp32Buf_.Get<float>(tLen);
        AscendC::Add(xFp32, hsFp32, resFp32, tLen);

        auto yFp32 = yFp32Buf_.Get<float>(tLen);
        AscendC::Muls(yFp32, xFp32, invRms, tLen);
        AscendC::Mul(yFp32, yFp32, wFp32, tLen);

        CastOutput(outLocal_, yFp32, tLen);
        AscendC::PipeBarrier<PIPE_V>();

        hsQueue_.FreeTensor(hsLocal_);
        resQueue_.FreeTensor(resLocal_);
        wQueue_.FreeTensor(wLocal_);
        outQueue_.EnQue(outLocal_);
    }

    __aicore__ inline void CopyOutPhase2(uint64_t rowColOff, int32_t tLen)
    {
        outLocal_ = outQueue_.DeQue<dataType>();
        StoreUbToGm(outGM_[rowColOff], outLocal_, static_cast<uint32_t>(tLen));
        outQueue_.FreeTensor(outLocal_);
    }

    template <typename SrcT>
    __aicore__ inline AscendC::LocalTensor<float> CastInput(
        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf,
        AscendC::LocalTensor<SrcT> &src, int32_t count)
    {
        if constexpr (std::is_same_v<SrcT, float>) {
            return src.template ReinterpretCast<float>();
        } else {
            auto dst = buf.Get<float>(count);
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            return dst;
        }
    }

    template <typename DstT>
    __aicore__ inline void CastOutput(
        AscendC::LocalTensor<DstT> &dst,
        AscendC::LocalTensor<float> &src, int32_t count)
    {
        if constexpr (std::is_same_v<DstT, float>) {
            AscendC::DataCopy(dst, src, count);
        } else {
            AscendC::RoundMode rm = AscendC::RoundMode::CAST_ROUND;
            AscendC::Cast(dst, src, rm, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    int32_t B_, H_, usedCoreNum_, tasksPerCore_, blockM_, mNum_;
    int32_t tileH_, numTilesH_, lastTileH_;
    float eps_;
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<dataType> hsGM_, resGM_, wGM_, outGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsQueue_, resQueue_, wQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> hsFp32Buf_, resFp32Buf_, xFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wFp32Buf_, yFp32Buf_, sqFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkBuf_, sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sqSumBuf_, rmsValBuf_, rmsSqrtBuf_;
    AscendC::LocalTensor<dataType> hsLocal_, resLocal_, wLocal_, outLocal_;
};

extern "C" __global__ __aicore__ void fused_add_rmsnorm_kernel(
    GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR output,
    int32_t B, int32_t H, int32_t usedCoreNum, int32_t tasksPerCore,
    int32_t blockM, int32_t mNum, int32_t tileH, int32_t numTilesH,
    int32_t lastTileH, float eps, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        FusedAddRmsnormKernel<float> k;
        k.Init(hidden_states, residual, weight, output,
               B, H, usedCoreNum, tasksPerCore, blockM, mNum,
               tileH, numTilesH, lastTileH, eps);
        k.Process();
    } else if (dtypeFlag == 1) {
        FusedAddRmsnormKernel<half> k;
        k.Init(hidden_states, residual, weight, output,
               B, H, usedCoreNum, tasksPerCore, blockM, mNum,
               tileH, numTilesH, lastTileH, eps);
        k.Process();
    } else {
        FusedAddRmsnormKernel<bfloat16_t> k;
        k.Init(hidden_states, residual, weight, output,
               B, H, usedCoreNum, tasksPerCore, blockM, mNum,
               tileH, numTilesH, lastTileH, eps);
        k.Process();
    }
}
